"""Isolated native enemy fixture; unrelated spawns disabled outside the selected actor.
No enemy HP/clocks are changed after spawn. Stage geometry settles before placement.
"""
SETUP="([type,mode])=>{if(window.s1bProbeSpawn)spawnEnemy=window.s1bProbeSpawn;diffKey=mode;DIFF=difficultyForRun('arcade',mode);stagePlan=[];waveIdx=999;_adaptiveSpawnT=9999;spawnClock=9999;subBossDone=true;bossWarned=true;stageTimer=0;boss=null;subBoss=null;bossActive=subBossActive=false;enemies=[];eBullets=[];pBullets=[];powerups=[];playerLocks=[];groundTargetingFx=[];S1A.fx=[];S1A.events=[];S1A.draws={};_navalFlashes=[];player.invuln=1e9;player.dead=player.out=false;player.x=worldWidth()/2;player.y=VH-65;Input.keys.j=Input.keys.c=false;run.mode='campaign';debugFight=null;BOFCinematicDirector.cancel();setState(GS.PLAY);\n const heavy=/tank|truck|modturret/.test(type);mapScroll=heavy?levelScrollRange()*.52:0;drawWorld(0);for(let i=0;i<6;i++){window.__bofStepNow=(window.__bofStepNow||performance.now())+1000/60;loop(window.__bofStepNow);}window.chosen={x:worldWidth()/2,y:heavy?160:100};\n if(heavy){let found=false;for(let y=110;y<260&&!found;y+=10)for(let x=70;x<worldWidth()-70;x+=10)if(groundTrafficLegal({x,y,w:103,h:103},x,y)){chosen={x,y};found=true;break;}if(!found)throw Error('No legal ground fixture');player.x=clamp(chosen.x+170,50,worldWidth()-50);}\n const y=/s1jet/.test(type)?viewTopY()-80:chosen.y;window.E=spawnEnemy(type.startsWith('modturret')?'modturret':type,chosen.x,y,{route:'straight',_modWeapon:type==='modturret-missile'?'missile':'mg',_modStage:1});S1B.events=[];MT18.shots=0;window.s1bProbeSpawn=spawnEnemy;spawnEnemy=()=>null;window.trace=[];window.firstShot=false;window.firstTurn=false;window.firstLate=false;\n if(typeof VP12!=='undefined')VP12.next=99999;if(typeof CP12!=='undefined')CP12.next=99999;\n return{type,x:E.x,y:E.y,w:E.w,h:E.h,hp:E.hp,atk:E._atk,naval:E._naval,initialPlayerX:player.x,chosen};}"
